def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = set(v for row in grid for v in row if v != bg)

    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1, 1), (1, -1)):
            # Continue a diagonal run in its downward direction.
            starts = [(r, c) for r, c in pts
                      if (r - dr, c - dc) not in pts and (r + dr, c + dc) in pts]
            if starts:
                r, c = starts[0]
                while (r + dr, c + dc) in pts:
                    r, c = r + dr, c + dc
                r, c = r + dr, c + dc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == bg:
                        out[r][c] = color
                    r, c = r + dr, c + dc
    return out
